import re


class BaseAttribute:
    def __init__(self, name, **kwargs):
        self._name = name
        self._value = None

    @property
    def name(self):
        return self._name

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, v):
        self._verify(v)
        self._value = self._set_default(v)

    def _set_default(self, value):
        return value

    def _verify(self, value):
        pass

    def to_tuple(self):
        return self._name, self._value


class OptionalBoolAttribute(BaseAttribute):
    def __init__(self, name, default_value=None, repr="bool"):

        super().__init__(name)
        self._default_value = default_value or False
        self.value = self._default_value
        self._repr = repr

    def _verify(self, value):
        if not value:
            return  # optional

        if str(value).lower() not in ["true", "false"]:
            raise ValueError(
                "value must be in True, False, case insensitive of 'True', 'False'"
            )

    def _set_default(self, value):
        if not value:
            return self._default_value

        if str(value).lower() == "true":
            return True
        if str(value).lower() == "false":
            return False

    def to_tuple(self):
        if self._repr == "str":
            return self.name, str(self.value).lower()
        elif self._repr == "bool":
            return super().to_tuple()


class StrAttribute(BaseAttribute):
    def __init__(self, name, pattern=None):
        super().__init__(name)
        self._pattern = pattern

    def _verify(self, value):
        if not self._pattern:
            return
        matched = re.match(self._pattern, value)
        if not matched:
            raise ValueError(f"value must following the pattern {self._pattern}")


class RequiredStrAttribute(StrAttribute):
    def _verify(self, value):
        if not value:
            raise ValueError("required value must not be None or empty")
        super()._verify(value)


class OptionalStrAttribute(StrAttribute):
    def __init__(self, name, default_value=None, pattern=None):
        super().__init__(name, pattern=pattern)
        self._default_value = default_value or ""
        self.value = self._default_value

    def _verify(self, value):
        if not value:
            return
        super()._verify(value)

    def _set_default(self, value):
        if not value:
            return self._default_value
        return value


class OptionalStrEnumAttribute(BaseAttribute):
    def __init__(
        self, name, default_value=None, candidates=None, case_insensitive=True
    ):
        super().__init__(name)
        self._default_value = default_value or ""
        self._candidates = candidates or []
        self._case_insensitive = case_insensitive
        self.value = self._default_value

    def _verify(self, value):
        if not value:
            return  # optional

        try:
            self._find_item_index(value)
        except ValueError:
            raise ValueError(f"value must be in {self._candidates}")

    def _set_default(self, value):
        if not value:
            return self._default_value

        index = self._find_item_index(value)
        return self._candidates[index]

    def _find_item_index(self, value):
        test_value = value
        candidates = self._candidates
        if self._case_insensitive:
            candidates = [item.lower() for item in self._candidates]
            test_value = value.lower()
        return candidates.index(test_value)


class AttributeFactory:
    def __init__(self, attribute_name, **kwargs):
        self._attribute_name = attribute_name

    @property
    def attribute_name(self):
        return self._attribute_name

    def create(self, value):
        pass


class OptionalBoolAttributeFactory(AttributeFactory):
    def __init__(self, attribute_name, default_value=None, repr="bool"):
        super().__init__(attribute_name)
        self._default_value = default_value
        self._repr = repr

    def create(self, value):
        attr = OptionalBoolAttribute(
            self._attribute_name, self._default_value, self._repr
        )
        attr.value = value
        return attr


class RequiredStrAttributeFactory(AttributeFactory):
    def __init__(self, attribute_name, pattern=None):
        super().__init__(attribute_name)
        self._pattern = pattern

    def create(self, value):
        attr = RequiredStrAttribute(self._attribute_name, pattern=self._pattern)
        attr.value = value
        return attr


class OptionalStrAttributeFactory(AttributeFactory):
    def __init__(self, attribute_name, default_value=None, pattern=None):
        super().__init__(attribute_name)
        self._pattern = pattern
        self._default_value = default_value

    def create(self, value):
        attr = OptionalStrAttribute(
            self._attribute_name,
            default_value=self._default_value,
            pattern=self._pattern,
        )
        attr.value = value
        return attr


class OptionalStrEnumAttributeFactory(AttributeFactory):
    def __init__(
        self, attribute_name, default_value=None, candidates=None, case_insensitive=None
    ):
        super().__init__(attribute_name)
        self._candidates = candidates
        self._default_value = default_value
        self._case_insensitive = case_insensitive

    def create(self, value):
        attr = OptionalStrEnumAttribute(
            self._attribute_name,
            candidates=self._candidates,
            case_insensitive=self._case_insensitive,
        )
        attr.value = value
        return attr
